def packet_threat_analyzer(packet_data):
    # Assumes packet_data is a dictionary { 'Packet ID': {'Threat Level': X, 'Type': Y}, ... }
    threat_levels = {}
    packet_counts = {}

    for packet_id, info in packet_data.items():
        packet_type = info['Type']

        if packet_type not in threat_levels:
            threat_levels[packet_type] = []
            packet_counts[packet_type] = 0

        threat_levels[packet_type].append(info['Threat Level'])
        packet_counts[packet_type] += 1

